const ingredients = Array.from(document.querySelectorAll('[id*="ingredient"], .mntl-structured-ingredients__list-item')).map(el => el.textContent.trim()).filter(t => t);
const directions = Array.from(document.querySelectorAll('[id*="mntl-sc-block-html"], .mntl-sc-block-html')).map(el => el.textContent.trim()).filter(t => t);
return { 
  ingredientsCount: ingredients.length, 
  directionsCount: directions.length,
  fullIngredients: document.querySelector('.mntl-structured-ingredients__list')?.textContent.trim() || 'none',
  fullDirections: document.querySelector('.recipe-instructions')?.textContent.trim() || 'none'
};

const data = __data("Recipe")[0];
return {
  recipeIngredient: data.recipeIngredient,
  recipeInstructions: data.recipeInstructions.map(s => s.text),
  prepTime: data.prepTime,
  cookTime: data.cookTime,
  totalTime: data.totalTime,
  rating: data.aggregateRating
};

const data = __data("Recipe")[0];
// Get the full recipeIngredient if available
const all = data.recipeIngredient;
return {
  fullArray: all,
  count: all.length
};

// Find JSON-LD script and parse it directly
const jsonLdScripts = document.querySelectorAll('script[type="application/ld+json"]');
const recipes = [];
jsonLdScripts.forEach(s => {
  try {
    const data = JSON.parse(s.textContent);
    if (data['@type'] === 'Recipe' || (Array.isArray(data['@type']) && data['@type'].includes('Recipe'))) {
      recipes.push(data);
    }
  } catch (e) {}
});
if (recipes.length === 0) {
  // try @graph format
  jsonLdScripts.forEach(s => {
    try {
      const data = JSON.parse(s.textContent);
      if (data['@graph']) {
        data['@graph'].forEach(g => {
          if (g['@type'] === 'Recipe' || (Array.isArray(g['@type']) && g['@type'].includes('Recipe'))) {
            recipes.push(g);
          }
        });
      }
    } catch (e) {}
  });
}
return recipes.map(r => r.recipeIngredient);

// Try multiple approaches to find ingredient quantities
const result = {};

// Check if there are off-screen ingredient items
const allIngredients = document.querySelectorAll('li[class*="ingredient"], [class*="Ingredient"]');
result.count = allIngredients.length;

// Get ALL ingredient elements including hidden ones
const allItems = document.querySelectorAll('[itemprop="recipeIngredient"]');
result.itempropCount = allItems.length;

// Try the structured ingredient list
const structuredList = document.querySelector('.mntl-structured-ingredients__list');
if (structuredList) {
  const lis = structuredList.querySelectorAll('li');
  result.ingredientItems = Array.from(lis).map(li => li.textContent.trim());
}

return result;

// Try forcing them all to be visible and read text
const items = document.querySelectorAll('[itemprop="recipeIngredient"]');
const result = [];
for (let i = 0; i < items.length; i++) {
  result.push(items[i].textContent.trim());
}

// Also try direct query
const allByClass = document.querySelectorAll('.mntl-structured-ingredients__list-item, .recipe-ingredient__quantity-wrapper, .recipe-ingredient');
const result2 = [];
for (let i = 0; i < allByClass.length; i++) {
  result2.push(allByClass[i].textContent.trim());
}

return { byItemprop: result, byClass: result2, itemCount: items.length, classCount: allByClass.length };

// Get full recipe info from the page's hidden state
const allText = document.body.innerText;
// Get the full recipe ingredients section
const ingredientSection = document.body.innerHTML.match(/structured-ingredients[^]*?(?=Directions|Instructions|recipe-instructions)/);
return { hasMatch: !!ingredientSection, snippet: ingredientSection ? ingredientSection[0].substring(0, 5000) : 'not found' };

const ingredientList = document.querySelector('.mm-recipes-structured-ingredients__list');
if (ingredientList) {
  const items = ingredientList.querySelectorAll('li');
  const result = [];
  for (let li of items) {
    const quantitySpan = li.querySelector('[data-ingredient-quantity]');
    const nameSpan = li.querySelector('[data-ingredient-name]');
    const noteSpan = li.querySelector('[data-ingredient-notes]');
    result.push({
      qty: quantitySpan?.textContent.trim(),
      name: nameSpan?.textContent.trim(),
      note: noteSpan?.textContent.trim(),
      full: li.textContent.trim().replace(/\s+/g, ' ')
    });
  }
  return result;
}
return 'not found';
